static uint64_t sRng;
static uint32_t R(uint32_t n) { sRng = sRng * 6364136223846793005ull + 1442695040888963407ull; return (uint32_t)(sRng >> 33) % n; }
static const wchar_t* kNames[] = {L"Room A", L"Room B", L"Game 1", L"Game 2", L"bob", L"a b", L"x"};
static const char* kNamesA[] = {"Room A", "Room B", "Game 1", "Game 2", "bob", "a b", "nope"};
static const char* kChats[] = {"xxhello", "a", "xx/i bob", "xx/I \"a b\" z", "xx/u bob", "xx/u nobody", "xx/t bob hi there",
                               "xx/t \"a b\" yo", "xx/T x ab", "xx/r back", "xx/r", "xx/w x", "xx/q what", "xx/i", "xx/t \"a b"};
static const long kStatuses[] = {WS_Success, WS_Success, WS_Success, WS_Killed, WS_RoutingServG2_GroupAlreadyExists,
                                 WS_RoutingServG2_InvalidPassword, WS_RoutingServG2_ClientAlreadyInGroup,
                                 WS_RoutingServG2_ClientAlreadyExists, -1};

static void PutU32(std::string& s, uint32_t v) { s.append((const char*)&v, 4); }
static void PutU16(std::string& s, uint16_t v) { s.append((const char*)&v, 2); }
// a game record: version 1 (UWideString::Export's texts) or an older one (C strings)
static std::string GameRecord()
{
    std::string s;
    const char* texts[3] = {kNamesA[R(7)], R(2) ? "10.0.0.1:5" : "", R(3) ? "" : "pw"};
    if (R(4)) {
        PutU16(s, 1);
        for (const char* t : texts) { PutU32(s, (uint32_t)strlen(t) + 2); s += t; s += std::string(2, '\0'); }
    } else {
        s += texts[0]; s += '\0'; s += texts[1]; s += '\0'; s += texts[2]; s += '\0';
    }
    PutU32(s, R(9)); PutU32(s, R(9)); PutU32(s, R(4)); PutU32(s, R(4)); PutU16(s, (uint16_t)(R(2) ? sLastJoin : R(3) + 10));
    s += std::string(24, '\0');   // slack: an older record's reads past its texts stay inside the buffer
    return s;
}
static std::string WideRecord(const char* t)
{
    std::string s;
    for (const char* p = t; *p; p++) { wchar_t c = *p; s.append((const char*)&c, sizeof(wchar_t)); }
    // slack: read as a game record (the game list takes every object), its reads stay inside the buffer (the
    // original read past a short one; the Rust reads zeros there)
    return s + std::string(24, '\0');
}
static void DrawWorld()
{
    sK = Knobs();
    int groups = R(5);
    for (int i = 0; i < groups; i++) {
        GroupKnob g;
        g.mName = kNames[R(4)];
        g.mId = (unsigned short)(10 + R(4));
        g.mFlags = R(2) ? 0x800 : 0;
        g.mMembers = (unsigned short)R(20);
        for (int m = R(3); m > 0; m--) g.mMemberIds.push_back((unsigned short)(1 + R(4)));
        sK.mGroups.push_back(g);
    }
    for (int i = 1; i <= 4; i++)
        if (R(3)) sK.mClients.push_back(ClientKnob{(unsigned short)i, kNames[4 + R(3)]});
    sK.mMyClientId = (unsigned short)(1 + R(4));
    const long forms[] = {kFormAvailableGames, kFormLobby, kFormMainMenu};
    sK.mCurrentForm = forms[R(3)];
    for (bool& c : sK.mChecks) c = R(2) != 0;
    sK.mEmailChecked = R(2) != 0;
    sK.mRoomsSelection = (long)R(4) - 1;
    sK.mRoomsLines = R(4);
    sK.mWonNetExists = R(8) != 0;
    sK.mKeyValid = R(2) != 0;
    sK.mFileOpens = R(4) != 0;
    for (int i = R(15); i > 0; i--) sK.mFileLines.push_back(R(3) ? "10.0.0." + std::to_string(i) + ":15101\n" : "host" + std::to_string(i));
}
static void DrawOp(OpKnob& k)
{
    k.mStatus = kStatuses[R(9)];
    k.mType = (int)R(64);
    k.mGroup = R(2) ? sLastJoin : (unsigned short)(10 + R(4));
    k.mLink = (unsigned short)(10 + R(4));
    k.mClient = (unsigned short)(1 + R(5));
    k.mFlags16 = R(8);
    k.mMaxPlayers = R(70000);
    k.mReconnect = R(1000);
    k.mText = kNames[R(7)];
    k.mRecipients = R(4) != 0;
    k.mHasData = R(8) != 0;
    k.mData = GameRecord();
    for (int i = R(4); i > 0; i--) {
        int t = R(3);
        ObjectKnob o{(unsigned short)(10 + R(4)), t == 0 ? "EE Game Object" : t == 1 ? "EE Room Object" : "Other", ""};
        o.mData = t == 1 ? WideRecord(kNamesA[R(7)]) : GameRecord();
        k.mObjects.push_back(o);
    }
    for (int i = R(4); i > 0; i--) k.mMembers.push_back((unsigned short)(1 + R(5)));
    for (int i = 1; i <= 4; i++)
        if (R(2)) k.mClients.push_back(ClientKnob{(unsigned short)i, kNames[4 + R(3)]});
    k.mOnRouting = R(6) != 0;
    k.mSocketIsRouting = R(6) != 0;
    k.mWhichOp = R(3);
    k.mNewsletter = R(2);
    k.mEmail = R(2) ? "a@b.c" : "";
    for (int i = R(4); i > 0; i--) k.mEntities.push_back(R(2) ? L"TitanRoutingServerG2" : L"Other");
}

