static int CallIndex(CompletionBase<AsyncOpPtr>* c)
{
    if (Ori::EEWonNetCompletion* e = dynamic_cast<Ori::EEWonNetCompletion*>(c))
        for (int i = 0; i < kCallCount; i++) if (e->mCallback == kOrigCalls[i]) return i;
    if (Ori::RoutingCompletion* e = dynamic_cast<Ori::RoutingCompletion*>(c))
        for (int i = 0; i < kCallCount; i++) if (e->mCallback == kOrigCalls[i]) return i;
    if (Rus::WonNetCompletion* e = dynamic_cast<Rus::WonNetCompletion*>(c))
        for (int i = 0; i < kCallCount; i++) if (e->mCall == kNewCalls[i]) return i;
    return -1;
}
static std::string CompletionName(CompletionBase<AsyncOpPtr>* c)
{
    bool routing = dynamic_cast<Ori::RoutingCompletion*>(c) != NULL ||
                   (dynamic_cast<Rus::WonNetCompletion*>(c) != NULL && dynamic_cast<Rus::WonNetCompletion*>(c)->mRouting);
    int i = CallIndex(c);
    return std::string(routing ? "route:" : "net:") + (i < 0 ? "?" : kCallNames[i]);
}
static std::string CallbackName(void (*cb)(UIForm*))
{
    if (cb == NULL) return "NULL";
    if (cb == Ori::CloseMessageCallback || cb == Rus::CloseMessageCallback) return "close";
    if (cb == Ori::CancelConnectCallback || cb == Rus::CancelConnectCallback) return "cancel";
    if (cb == Ori::CancelOpCallback || cb == Rus::CancelOpCallback) return "cancel op";
    if (cb == Ori::HostGameCallback || cb == Rus::HostGameCallback) return "host";
    return "?";
}

// ---- the original's members as the Rust's dump writes its data
static std::string Info(Ori::OrigNet* o, const EEWonNetGameInfo& g)
{
    char b[96];
    snprintf(b, sizeof b, " %u %u %u %u %u", g.mHumans, g.mPlayers, g.mHostClientId, g.mFlags, g.mRoomGroupId);
    return std::string((const char*)g.mGameName) + "|" + (const char*)g.mAddress + "|" + (const char*)g.mPassword + "|" + (b + 1);
}
static std::string OrigDump(Ori::OrigNet* o)
{
    auto w = [&](const std::wstring& s) { return o->ToString(s); };
    char b[256];
    std::string s = "pw=" + w(o->mPassword) + " game=" + w(o->mGameName) + " room=" + w(o->mRoomName) + " cur=" +
                    w(o->mCurrentRoom) + " server=" + w(o->mServerName);
    snprintf(b, sizeof b, " ids %u %u %u %u %u %u flags %d%d%d%d%d%d%d l %d %d\n", o->mJoinGroupId, o->mGameGroupId,
             o->mReplyClientId, o->mJoinRoomId, o->mGameListPort, o->mRoomGroupId, o->mIsBehindFirewall, o->mB187,
             o->mIgnoreClose, o->mIsListingPlayers, o->mRoomListChanged, o->mGamesChanged, o->mB18E, (int)o->mL168,
             (int)o->mL16C);
    s += b;
    s += "info " + Info(o, o->mGameInfo) + "\n";
    for (auto& g : o->mGames) s += "game " + std::to_string(g.first) + " " + Info(o, g.second) + "\n";
    for (auto& r : o->mRooms) {
        snprintf(b, sizeof b, "|%lu %lu\n", (unsigned long)r.second.mMaxPlayers, (unsigned long)r.second.mId);
        s += "room " + std::to_string(r.first) + " " + (const char*)r.second.mName + "|" + (const char*)r.second.mDescription + b;
    }
    for (auto& c : o->mClients) s += "client " + std::to_string(c.first) + " " + w(c.second) + "\n";
    for (auto& d : o->mDirectoryServers) s += "dir " + d + "\n";
    return s;
}
// ---- the run
struct Side {
    bool orig;
    Ori::OrigNet* o = NULL;
    Rus::EEWonNet* n = NULL;
    std::vector<std::string> trace;
    std::vector<std::string> dumps;
};

static void Note(const std::string& s) { Log("== " + s); }

static std::string NewDumpOf(Rus::EEWonNet* n);

static void RunSide(Side& side, uint64_t seed, int steps)
{
    sRng = seed;
    sTrace.clear();
    sPending.clear();
    sLockIds = 0;
    gWonClientId = 0;
    sLastJoin = 10;   // a global both sides write: each starts from the game's zero
    sEventIds = 0;
    DrawWorld();
    AuthContext* user = new AuthContext;
    if (side.orig) {
        Ori::OrigNet* o = new Ori::OrigNet;
        o->mAuthServers = NULL;
        o->mUser = user;
        // the original constructor left the joined game's numbers uninitialised (the Rust's are zero)
        o->mGameInfo.mHumans = o->mGameInfo.mPlayers = o->mGameInfo.mHostClientId = o->mGameInfo.mFlags = 0;
        o->mGameInfo.mRoomGroupId = 0;
        side.o = o;
        sRoutingNow = [o]() -> RefCount* { return o->mRouting.get(); };
        sFormArgName = [o](UIForm* f) -> std::string {
            if (f == NULL) return "NULL";
            if ((void*)f == (void*)&o->mCancelled) return "cancelled";
            if ((void*)f == (void*)&o->mJoinRoomCancelled) return "joincancelled";
            if ((void*)f == (void*)o) return "self";
            if ((void*)f == (void*)o->mAccountOp.get()) return "accountop";
            return "?";
        };
    } else {
        Rus::EEWonNet* n = new Rus::EEWonNet;
        n->mUser = user;
        side.n = n;
        sRoutingNow = [n]() -> RefCount* { return n->mRouting.get(); };
        sFormArgName = [n](UIForm* f) -> std::string {
            if (f == NULL) return "NULL";
            if ((void*)f == (void*)&n->mCancelled) return "cancelled";
            if ((void*)f == (void*)&n->mJoinRoomCancelled) return "joincancelled";
            if ((void*)f == (void*)n) return "self";
            if ((void*)f == (void*)n->mAccountOp.get()) return "accountop";
            return "?";
        };
    }
    Ori::OrigNet* o = side.o;
    Rus::EEWonNet* n = side.n;
    auto dump = [&]() { return side.orig ? OrigDump(o) : NewDumpOf(n); };
    auto call = [&](Call c, intptr_t a, intptr_t b, intptr_t d) { return ee_won_wonnet_call(n->mRust, c, a, b, d); };
    side.dumps.push_back(dump());
    // the original dereferenced the routing connection unchecked in SendChat, OnChat, UpdateGameObject and
    // CreateGameCallback's success (a crash without one, both sides): those steps get one first
    auto ensureRouting = [&]() {
        if (side.orig ? o->mRouting.get() == NULL : n->mRouting.get() == NULL) {
            Log("routing given");
            if (side.orig) o->mRouting = new SmartRoutingConnection; else n->mRouting = new SmartRoutingConnection;
        }
    };
    for (int step = 0; step < steps; step++) {
        // the world may change between steps
        if (R(3) == 0) DrawWorld();
        Ori::gWonNet = sK.mWonNetExists ? o : NULL;
        Rus::gWonNet = sK.mWonNetExists ? n : NULL;
        int what = (int)R(40);
        Note("step " + std::to_string(what));
        const char* name = kNamesA[R(7)];
        const char* pw = R(3) ? NULL : (R(2) ? "secret" : "");
        switch (what) {
        case 0: case 1:   // a routing connection, as SelectServer or Initialize leave one
            if (side.orig) o->mRouting = new SmartRoutingConnection; else n->mRouting = new SmartRoutingConnection;
            break;
        case 2: { std::wstring w = kNames[R(7)]; IPAddr a("9.9.9.9:" + std::to_string(R(9)));
            if (side.orig) o->SelectServer(w, a); else call(Call::SelectServer, (intptr_t)w.data(), w.length(), (intptr_t)&a); break; }
        case 3: if (side.orig) o->HostGame(name, pw); else call(Call::HostGame, (intptr_t)name, (intptr_t)pw, 0); break;
        case 4: if (side.orig) o->JoinGame(name, pw); else call(Call::JoinGame, (intptr_t)name, (intptr_t)pw, 0); break;
        case 5: if (side.orig) o->JoinRoom(name, pw); else call(Call::JoinRoom, (intptr_t)name, (intptr_t)pw, 0); break;
        case 6: if (side.orig) o->LeaveRoom(); else call(Call::LeaveRoom, 0, 0, 0); break;
        case 7: { EEWonNetGameInfo g; g.mGameName = "kept"; g.mAddress = "a"; g.mPassword = ""; g.mHumans = 7; g.mPlayers = 7; g.mHostClientId = 7; g.mFlags = 7; g.mRoomGroupId = 7;
            if (side.orig) o->GetGameInfo(g); else call(Call::GetGameInfo, (intptr_t)&g, 0, 0);
            Log("info out " + Info(NULL, g)); break; }
        case 8: { EEWonNetGameInfo g; g.mGameName = name; g.mAddress = "1.1.1.1"; g.mPassword = pw ? pw : ""; g.mHumans = R(9); g.mPlayers = R(9); g.mHostClientId = R(5); g.mFlags = R(4); g.mRoomGroupId = (unsigned short)R(20);
            if (side.orig) o->SetGameInfo(g); else call(Call::SetGameInfo, (intptr_t)&g, 0, 0); break; }
        case 9: if (side.orig) o->ClearGameList(); else call(Call::ClearGameList, 0, 0, 0); break;
        case 10: { bool f = R(2) != 0; bool r = side.orig ? o->RejoinRoom(f) : call(Call::RejoinRoom, f, 0, 0) != 0; Log("rejoin " + N(r)); break; }
        case 11: if (side.orig) o->RefreshGameList(NULL); else call(Call::RefreshGameList, 0, 0, 0); break;
        case 12: case 13: if (side.orig) o->UpdateGameList(); else call(Call::UpdateGameList, 0, 0, 0); break;
        case 14: { UWideString a(name), b(pw ? pw : "x"); bool f = R(2) != 0;
            if (side.orig) o->UpdateAccount(a, b, f); else call(Call::UpdateAccount, (intptr_t)(const char*)a, (intptr_t)(const char*)b, f); break; }
        case 15: if (side.orig) o->OpenUpdateAccount(); else call(Call::OpenUpdateAccount, 0, 0, 0); break;
        case 16: case 17: { ensureRouting(); UWideString t(kChats[R(15)]); if (side.orig) o->SendChat(t); else call(Call::SendChat, (intptr_t)(const char*)t, 0, 0); break; }
        case 18: { W::EEUICWonNetRoomsBox box; UIForm* f = gUIManager->GetFormByID(kFormAvailableRooms);
            W::UITextLabel* l16 = (W::UITextLabel*)f->GetControl(16); W::UITextLabel* l14 = (W::UITextLabel*)f->GetControl(14);
            if (side.orig) o->UpdateRoomList(&box, l16, l14); else call(Call::UpdateRoomList, (intptr_t)&box, (intptr_t)l16, (intptr_t)l14); break; }
        case 19: if (side.orig) o->CreateGame(); else call(Call::CreateGame, 0, 0, 0); break;
        case 20: if (side.orig) o->Disconnect(); else call(Call::Disconnect, 0, 0, 0); break;
        case 21: if (side.orig) o->ConnectToLobby(); else call(Call::ConnectToLobby, 0, 0, 0); break;
        case 22: { long t = (long)R(100); if (side.orig) o->FnCFFDD(t); else call(Call::FnCFFDD, t, 0, 0); break; }
        case 23: if (side.orig) o->FnCFFF2(); else call(Call::FnCFFF2, 0, 0, 0); break;
        case 24: { bool r = side.orig ? o->Initialize() : call(Call::Initialize, 0, 0, 0) != 0; Log("init " + N(r)); break; }
        case 25: if (side.orig) o->Login(name, pw); else call(Call::Login, (intptr_t)name, (intptr_t)pw, 0); break;
        case 26: if (side.orig) o->GetTitanServerList(); else call(Call::GetTitanServerList, 0, 0, 0); break;
        case 27:   // a lobby and its window
            if (side.orig) { o->mLobby = R(2) ? new WONAPICore : NULL; o->mLobbyWindow = R(2) ? new WONLobbyWindow : NULL; }
            else { n->mLobby = R(2) ? new WONAPICore : NULL; n->mLobbyWindow = R(2) ? new WONLobbyWindow : NULL; }
            break;
        case 28: ensureRouting(); if (side.orig) o->UpdateGameObject(); else call(Call::UpdateGameObject, 0, 0, 0); break;
        case 29: if (side.orig) o->LeaveGroups(); else call(Call::LeaveGroups, 0, 0, 0); break;
        case 30: case 31: {   // into a room's game list: a room joined, its answer, its games, the list shown
            ensureRouting();
            GroupKnob g{L"Room A", (unsigned short)(10 + R(4)), 0x800, 5, {}};
            sK.mGroups.push_back(g);
            if (side.orig) o->JoinRoom("Room A", NULL); else call(Call::JoinRoom, (intptr_t)"Room A", 0, 0);
            Call steps[2] = {Call::JoinRoomCallback, Call::ListGamesCallback};
            for (int k = 0; k < 2; k++) {
                int ci = k == 0 ? 10 : 0;   // kCallNames' JoinRoomCallback, ListGamesCallback
                SmartPtr<CompletionBase<AsyncOpPtr> > c;
                if (side.orig) c = new Ori::RoutingCompletion(kOrigCalls[ci]); else c = new Rus::WonNetCompletion(steps[k], true);
                RoutingOp* op = new RoutingOp;
                DrawOp(op->mK);
                op->mK.mStatus = WS_Success;
                op->mK.mGroup = g.mId;
                op->mK.mOnRouting = true;
                AsyncOpPtr hold(op);
                sRecordOp = op;
                c->Complete(hold);
            }
            sK.mCurrentForm = kFormAvailableGames;
            if (side.orig) o->UpdateGameList(); else call(Call::UpdateGameList, 0, 0, 0);
            break;
        }
        default: {  // a pending completion finishes
            SmartPtr<CompletionBase<AsyncOpPtr> > c;
            if (sPending.empty() || R(2)) {
                // a completion of a drawn call made here (as the server's notices reach the handlers SelectServer
                // installs): the original's class or the Rust's of the same call
                int k = (int)R(kCallCount);
                std::string name = kCallNames[k];
                // the server ops' calls never get a routing completion (it reads the op as a RoutingOp)
                bool routing = R(4) != 0 && name != "UpdateAccountCallback" && name != "GetAccountCallback" &&
                               name != "LoginCallback" && name != "GetTitanServerListCompletion";
                if (side.orig)
                    c = routing ? (CompletionBase<AsyncOpPtr>*)new Ori::RoutingCompletion(kOrigCalls[k])
                                : (CompletionBase<AsyncOpPtr>*)new Ori::EEWonNetCompletion(kOrigCalls[k]);
                else
                    c = new Rus::WonNetCompletion(kNewCalls[k], routing);
            } else {
                size_t i = R((uint32_t)sPending.size());
                c = sPending[i];
                sPending.erase(sPending.begin() + i);
            }
            int k = CallIndex(c.get());
            OpKnob knob;
            DrawOp(knob);
            std::string cn = k < 0 ? "?" : kCallNames[k];
            if (cn == "OnChat" || cn == "CreateGameCallback") ensureRouting();
            // a data object without a buffer faulted the original (a NULL read); the Rust reads an empty record
            if (cn == "OnDataObjectCreated" || cn == "OnDataObjectModified" || cn == "JoinGameDataCallback") knob.mHasData = true;
            AsyncOp* op;
            if (cn == "LoginCallback" && knob.mWhichOp == 1 && (side.orig ? o->mLoginOp.get() : n->mLoginOp.get()))
                op = side.orig ? (AsyncOp*)o->mLoginOp.get() : (AsyncOp*)n->mLoginOp.get();
            else if (cn == "GetTitanServerListCompletion" && knob.mWhichOp == 2 && (side.orig ? o->mDirOp.get() : n->mDirOp.get()))
                op = side.orig ? (AsyncOp*)o->mDirOp.get() : (AsyncOp*)n->mDirOp.get();
            else if (cn == "UpdateAccountCallback" || cn == "GetAccountCallback" || cn == "GetTitanServerListCompletion" || cn == "LoginCallback")
                op = new RustServerOp;
            else
                op = new RoutingOp;
            op->mK = knob;
            AsyncOpPtr hold(op);
            sRecordOp = (RoutingOp*)op;
            Note("complete " + CompletionName(c.get()));
            c->Complete(hold);
            break;
        }
        }
        // the readers
        if (side.orig)
            Log("read " + N(o->mGameListPort) + " " + N(o->mRoomListChanged) + " " + N(o->mIsBehindFirewall) + " " + WS(o->mRoomName));
        else
            Log("read " + N(call(Call::GameListPort, 0, 0, 0)) + " " + N(call(Call::RoomListChanged, 0, 0, 0)) + " " +
                N(call(Call::IsBehindFirewall, 0, 0, 0)) + " " + [&]() { std::wstring s; call(Call::RoomName, (intptr_t)&s, 0, 0); return WS(s); }());
        side.dumps.push_back(dump());
    }
    Note("destroy");
    Ori::gWonNet = NULL;
    Rus::gWonNet = NULL;
    if (side.orig)
        delete o;
    else
        delete n;
    sPending.clear();
    side.trace = sTrace;
}

// the Rust's data as its dump writes it
static std::string NewDumpOf(Rus::EEWonNet* n) { return std::string(ee_won_wonnet_dump_text(n->mRust)); }

static long long sRows[8];   // the rows (game 3, player 4, chat 6 and 7) posted with a real text
int main(int argc, char** argv)
{
    int sequences = argc > 1 ? atoi(argv[1]) : 200000;
    sCompletionName = CompletionName;
    sCallbackName = CallbackName;
    ee_won_wonnet_set_host(Rus::WonNetHost);
    int bad = 0;
    long long steps = 0;
    for (int s = 0; s < sequences; s++) {
        uint64_t seed = 0x9e3779b97f4a7c15ull * (uint64_t)(s + 1);
        sRng = seed;
        int count = 1 + (int)R(16);
        Side a{true}, b{false};
        RunSide(a, seed, count);
        RunSide(b, seed, count);
        steps += count;
        for (const std::string& t : a.trace)
            if (t.compare(0, 12, "ui post won ") == 0 && t.find("@@@") == std::string::npos) sRows[(t[12] - '0') & 7]++;
        bool same = a.trace == b.trace && a.dumps == b.dumps;
        if (!same) {
            if (bad < 3) {
                printf("sequence %d (seed %llx) mismatches\n", s, (unsigned long long)seed);
                size_t i = 0;
                while (i < a.trace.size() && i < b.trace.size() && a.trace[i] == b.trace[i]) i++;
                for (size_t k = i > 6 ? i - 6 : 0; k < i + 4 && (k < a.trace.size() || k < b.trace.size()); k++)
                    printf("  %c %-60s | %s\n", k == i ? '>' : ' ', k < a.trace.size() ? a.trace[k].c_str() : "-",
                           k < b.trace.size() ? b.trace[k].c_str() : "-");
                for (size_t k = 0; k < a.dumps.size() && k < b.dumps.size(); k++)
                    if (a.dumps[k] != b.dumps[k]) { printf("  dump %zu:\n--- orig\n%s--- rust\n%s", k, a.dumps[k].c_str(), b.dumps[k].c_str()); break; }
            }
            bad++;
        }
    }
    printf("rows: games %lld, players %lld, chat %lld + %lld\n", sRows[3], sRows[4], sRows[6], sRows[7]);
    int ops = 0, hit = 0;
    for (int i = 0; i <= (int)EeWonNetOp::InfoSetRoom; i++) {
        ops++;
        if (Rus::sOpHits[i]) hit++; else printf("host op %d not reached\n", i);
    }
    printf("won_wonnet_test: %d sequences, %lld steps, host ops reached %d of %d, %d mismatches\n", sequences, steps, hit, ops, bad);
    return bad;
}
